import pytest
from solution import PasswordValidator

@pytest.fixture
def pv():
    return PasswordValidator()

def test_valid_password(pv):
    ok, errors = pv.validate('MyP@ss1ng!')
    assert ok is True
    assert errors == []

def test_too_short(pv):
    ok, errors = pv.validate('Ab1!')
    assert ok is False
    assert any('length' in e.lower() or 'short' in e.lower() or 'character' in e.lower() for e in errors)

def test_no_uppercase(pv):
    ok, errors = pv.validate('myp@ss1ng!')
    assert ok is False

def test_no_digit(pv):
    ok, errors = pv.validate('MyP@ssing!')
    assert ok is False

def test_no_special(pv):
    ok, errors = pv.validate('MyPassw0rd')
    assert ok is False

def test_common_password(pv):
    ok, errors = pv.validate('password123')
    assert ok is False

def test_strength_weak(pv):
    assert pv.check_strength('abc') == 'weak'

def test_strength_strong(pv):
    assert pv.check_strength('MyV3ry$tr0ng!Pass') == 'strong'
